import json
from pathlib import Path
from html import escape as e
root = Path(__file__).resolve().parent
c = json.loads((root/'content.json').read_text())
css = '''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;background:#faf7f3;color:#302c35;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.85}a{color:#784250;text-underline-offset:4px;overflow-wrap:anywhere}a:focus-visible{outline:3px solid #784250;outline-offset:4px}header{border-bottom:1px solid #e9ded8;background:#fffdf9}header>div,main,footer{max-width:880px;margin:auto;padding:28px 28px}header>div{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.brand{font-weight:750;letter-spacing:.02em;text-decoration:none}.badge{font-size:12px;letter-spacing:.15em;color:#8e6e73}nav{display:flex;gap:20px;flex-wrap:wrap}h1{font-size:clamp(36px,7vw,58px);line-height:1.25;letter-spacing:-.04em;margin:12px 0 20px}h2{font-size:22px;line-height:1.45;margin:0 0 12px;letter-spacing:-.02em}p{margin:0 0 18px}.lead{font-size:18px;color:#655d67}.meta{display:flex;gap:10px;flex-wrap:wrap;font-size:14px;color:#746672}.meta span{border:1px solid #e3d6cf;border-radius:100px;padding:3px 12px}.hero{padding:30px 0 36px}.document{padding:34px 0 0;border-top:1px solid #ddcec6;margin-bottom:58px}.document>h2{font-size:30px;margin-bottom:16px}.clause{padding:24px 0;border-bottom:1px solid #e9ded8}.clause p{margin:0;overflow-wrap:anywhere}.links{margin-top:26px;padding:22px;background:#f1e9e3;border-radius:12px;display:flex;gap:20px;flex-wrap:wrap}footer{border-top:1px solid #e3d6cf;font-size:13px;color:#756c76;padding-bottom:40px}code{font-size:12px;overflow-wrap:anywhere}body:has(#en:target) .hero,body:has(#ja:target) .hero{display:none}@media(max-width:480px){header>div,main,footer{padding-left:20px;padding-right:20px}.hero{padding-top:24px}.clause{padding:21px 0}h2{font-size:20px}nav{gap:16px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white}header{position:static}nav{display:none}.document{break-before:page}.clause{break-inside:avoid}a{color:inherit}}'''
nav=''.join(f'<a href="#{x["code"]}" lang="{x["code"]}">{e(x["label"])}</a>' for x in c['languages'])
parts=[]
for lang in c['languages']:
    clauses=''.join(f'<section class="clause"><h3>{i}. {e(h)}</h3><p>{e(t)}</p></section>' for i,(h,t) in enumerate(lang['sections'],1))
    labels={'ko':('개인정보처리방침','Google Play 환불 안내'),'en':('Privacy Policy','Google Play refunds'),'ja':('プライバシーポリシー','Google Playの払い戻し')}[lang['code']]
    parts.append(f'<article class="document" id="{lang["code"]}" lang="{lang["code"]}"><h2>{e(lang["app"])} · {e(lang["title"])}</h2><p class="lead">{e(lang["intro"])}</p><p class="meta"><span>{e(lang["dateLabel"])}: {c["date"]}</span><span>Ebakssa Games</span></p>{clauses}<div class="links"><a href="{e(c["privacy"])}#{lang["code"]}">{labels[0]}</a><a href="https://support.google.com/googleplay/answer/2479637?hl={lang["code"]}">{labels[1]}</a></div></article>')
html=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="두근두근 다이스 · Doki Doki Dice · ドキドキダイス — Ebakssa Games 이용약관 / Terms of Service / 利用規約"><meta name="theme-color" content="#faf7f3"><title>두근두근 다이스 이용약관 | Doki Doki Dice Terms of Service</title><style>{css}</style></head><body><header><div><a class="brand" href="/">Doki Doki Dice <span aria-hidden="true">♡</span></a><nav aria-label="Language / 언어 / 言語">{nav}</nav></div></header><main><div class="hero"><span class="badge">EBAKSSA GAMES · LEGAL</span><h1>이용약관</h1><p class="lead">Terms of Service · 利用規約</p><p>두근두근 다이스 / Doki Doki Dice / ドキドキダイス</p></div>{''.join(parts)}</main><footer><p>© 2026 Ebakssa Games · Doki Doki Dice</p><p><a href="mailto:leesangkeun+ebakssa@gmail.com">leesangkeun+ebakssa@gmail.com</a><br><code>com.ebakssagames.dokidokidice</code></p></footer></body></html>'''
out=root/'public';out.mkdir(exist_ok=True)
(out/'index.html').write_text(html)
(out/'terms.html').write_text(html)
(out/'robots.txt').write_text('User-agent: *\nAllow: /\n')
print(f'Built {len(c["languages"])} languages, {sum(len(x["sections"]) for x in c["languages"])} clauses; {len(html.encode())} bytes')
